  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
  ON CONFLICT (clave) DO UPDATE SET tipo=EXCLUDED.tipo, pantalla_key=EXCLUDED.pantalla_key, titulo=EXCLUDED.titulo, resumen=EXCLUDED.resumen, fuentes=EXCLUDED.fuentes, revision=EXCLUDED.revision;
DO $verificacion$
BEGIN
  IF (SELECT count(*) FROM public.asistente_manual_fichas WHERE clave IN ('caja','como_usar_aria','compras_gastos','financiamiento','inicio_operaciones','proceso_caja_chica','proceso_solpe_pago','tesoreria')) <> 8 THEN
    RAISE EXCEPTION 'Sincronización del manual: se esperaban 8 fichas';
  END IF;
  IF (SELECT count(*) FROM public.asistente_manual_pasos WHERE ficha_clave IN ('caja','como_usar_aria','compras_gastos','financiamiento','inicio_operaciones','proceso_caja_chica','proceso_solpe_pago','tesoreria')) <> 52 THEN
