INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('caja','pantalla','caja','Caja Chica','Administra fondos de caja chica, sus egresos, aportes, rendiciones, arqueos y el cierre del fondo con saldo cero; permite editar y anular egresos y anular aportes desde el historial del fondo.','["src/pages_fin.jsx#CajaChica","src/components/NuevoEgreso.jsx#NuevoEgreso","src/components/CerrarFondoModal.jsx#CerrarFondoModal","src/services/cajaChicaService.js"]'::jsonb,'3d2ec4ac0a 2c804b78dc e7344f6212 2e9626399b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',1,'caja','caja','crear','Usa Nuevo fondo para crear un fondo con su responsable, importe, moneda y origen del dinero (cuenta bancaria o aporte directo). Mientras el fondo no tenga movimientos se puede modificar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',2,'caja',NULL,NULL,'Usa Nuevo egreso para registrar un gasto del fondo. El asistente tiene tres pasos: elige el tipo de gasto (puedes buscar por tipo o por categoría del Estado de Resultados), completa los datos del comprobante y del fondo, y revisa antes de confirmar. Lo puede registrar el responsable del fondo o quien tenga permiso de crear en Caja Chica.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',3,'caja',NULL,NULL,'En el paso de datos del egreso la categoría del Estado de Resultados es obligatoria y editable; la IA puede sugerirla a partir del tipo de gasto y la descripción. Adjunta el comprobante y vincula la OT si corresponde.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',4,'caja',NULL,NULL,'Usa Agregar aporte para reforzar el fondo con dinero de una cuenta bancaria o con un aporte directo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',5,'caja',NULL,NULL,'Usa Solicitar rendición para presentar los egresos del periodo; la solicitud queda disponible para revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',6,'caja','caja','aprobar','Revisa la rendición y usa Aprobar o Rechazar para continuar con la reposición del fondo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',7,'caja',NULL,NULL,'Usa Arqueo y luego Registrar arqueo con el efectivo contado; revisa las diferencias que muestra la pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',8,'caja','caja','editar','Usa Cerrar para cerrar el fondo. Ningún fondo puede cerrar con saldo a favor: transfiere el saldo a otra caja abierta de la misma moneda y sociedad, o devuélvelo a una cuenta bancaria activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',9,'caja',NULL,NULL,'Para corregir un egreso abre el fondo y, en Historial > Egresos, usa el botón Editar que aparece bajo el estado de la fila: puedes cambiar concepto, categoría del Estado de Resultados, centro de costo, número de comprobante y fecha. El monto no se edita; si está mal, anula el egreso y regístralo de nuevo. Lo puede hacer el responsable del fondo o quien tenga permiso de editar en Caja Chica, solo si el egreso está registrado y no cae en una rendición solicitada, aprobada o repuesta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',10,'caja',NULL,NULL,'Para anular un egreso o un aporte usa el botón Anular que aparece bajo el estado de la fila en Historial e indica el motivo. Un egreso anulado devuelve su monto al saldo y deja de contar en el Estado de Resultados. Un aporte solo lo anula quien tenga permiso de editar o anular en Caja Chica y siempre que el saldo del fondo no quede negativo; si vino de una cuenta bancaria, Tesorería registra el ingreso de reversión. Los anulados quedan visibles con su motivo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('como_usar_aria','proceso',NULL,'Cómo usar Aria','Cómo preguntarle a Aria escribiendo o dictando, cómo escuchar sus respuestas y cuántas consultas puedes hacer al día.','["src/components/AsistenteErpPanel.jsx#AsistenteErpPanelBase","src/components/AriaMicrofono.jsx#AriaMicrofono","src/lib/ariaHabla.js"]'::jsonb,'9faf34ba6e c65836e99c c4d45aa981')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',1,'ninguna',NULL,NULL,'Abre Aria con el robot de la esquina inferior derecha, disponible en las pantallas de Administración y de Operaciones, o escribe en el cuadro Pregúntale a Aria del Inicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',2,'ninguna',NULL,NULL,'Escribe tu pregunta y pulsa Enviar. Aria responde solo con la información que tus permisos te dejan ver y te indica qué módulos revisó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',3,'ninguna',NULL,NULL,'Para dictar, toca el micrófono, habla y vuelve a tocarlo al terminar; puedes hablar hasta un minuto. La primera vez el navegador te pedirá permiso para usar el micrófono.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',4,'ninguna',NULL,NULL,'Lo que dictaste aparece escrito en el cuadro para que lo revises o corrijas antes de enviarlo; nada se envía solo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',5,'ninguna',NULL,NULL,'Cuando preguntas por voz, Aria lee su respuesta en voz alta. Toca Detener voz para callarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',6,'ninguna',NULL,NULL,'Puedes hacer 30 preguntas y 60 dictados al día; los contadores se renuevan a medianoche, hora de Lima.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',7,'ninguna',NULL,NULL,'Aria puede preparar el registro de un gasto de caja chica, pero solo se guarda cuando tú lo confirmas en la tarjeta que te muestra.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('compras_gastos','pantalla','compras_gastos','Compras / Gastos','Consulta y registra compras y gastos con su comprobante, revisa los gastos que llegan desde campo y edita los que no dependen de otro módulo.','["src/pages_ops.jsx#ComprasGastos","src/components/NuevoEgreso.jsx#NuevoEgreso"]'::jsonb,'74938db849 2c804b78dc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',1,'compras_gastos',NULL,NULL,'Revisa los gastos y compras registrados con las pestañas Todos, Campo, Backoffice y Pendientes revisión. Usa la búsqueda y los filtros para localizar un documento o proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',2,'compras_gastos',NULL,NULL,'Usa Nuevo egreso para registrar una compra o gasto con el asistente de tres pasos: tipo de gasto, datos (fecha, monto, comprobante, proveedor, centro de costo, categoría del Estado de Resultados y método de pago) y revisión. Si el pago es por transferencia indica la cuenta bancaria; puedes vincular la orden de compra de origen y la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',3,'compras_gastos',NULL,NULL,'Los gastos registrados desde campo llegan como pendientes de revisión. Ábrelos, verifica el comprobante y usa Confirmar — marcar revisado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',4,'compras_gastos','caja','editar','Para editar un gasto ábrelo y usa Editar; la edición exige el permiso de edición de Caja. No se puede editar aquí si tiene una CxP generada, si viene de Personal/Nómina, si está registrado en Caja Chica o si se capitalizó como activo fijo; la pantalla indica dónde editarlo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('financiamiento','pantalla','financiamiento','Financiamiento y Deuda','Registra los préstamos, leasing y líneas de crédito de la empresa con su tabla de amortización, sus pagos y el reporte de deuda por moneda.','["src/pages_fin_deuda.jsx#FinanciamientoDeuda"]'::jsonb,'2095f9b5c2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',1,'financiamiento',NULL,NULL,'Revisa la deuda vigente, las cuotas e intereses del mes y el capital pendiente en los indicadores; los importes se muestran por moneda. Usa las pestañas Todos los préstamos, Vigentes, Cancelados y Reporte de deuda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',2,'financiamiento','financiamiento','crear','Usa Nuevo financiamiento para registrar un préstamo con su entidad, monto, moneda, tasa, plazo, meses de gracia, día de pago y tipo de cuota; la vista previa muestra la cuota estimada y al guardar se genera la tabla de amortización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',3,'financiamiento',NULL,NULL,'Usa Ver en un préstamo para abrir su resumen, la tabla de amortización, los pagos realizados y los documentos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',4,'financiamiento','financiamiento','editar','Desde el detalle usa Registrar pago / abono para pagar una cuota, abonar a capital o cancelar el saldo; el pago genera el egreso en Tesorería y el gasto de intereses.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',5,'financiamiento','financiamiento','editar','Usa Editar en la fila del préstamo para corregir cualquiera de sus datos. Las cuotas pagadas no cambian y las pendientes se recalculan sobre el saldo que queda; si ya tiene pagos, la moneda no se puede cambiar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',6,'financiamiento','financiamiento','anular','Usa Eliminar en la fila del préstamo. Tras la primera confirmación, una segunda alerta detalla todo lo que se borrará: cuotas, pagos, egresos de Tesorería por cuenta (cuyo saldo subirá) y gastos de intereses. Marca que lo entiendes y confirma; la acción no se puede deshacer.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inicio_operaciones','pantalla','app_operativo','Inicio de Operaciones con Aria','Muestra tu día en Operaciones: resumen de Aria, indicadores, pendientes por resolver de taller, producción, almacén, transporte, flota y compras, avisos, tus OT y accesos rápidos.','["operaciones-app/src/InicioOperaciones.jsx#InicioOperaciones","src/inicio/Inicio.jsx#InicioBase","src/inicio/datos.js"]'::jsonb,'29fababf8c 6912d1acde ab320441f0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',1,'app_operativo',NULL,NULL,'Al entrar a Operaciones se abre Inicio. Aria te saluda y resume tu día; Escuchar mi día lo lee en voz alta y Preséntame mi día recorre contigo los indicadores y pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',2,'app_operativo',NULL,NULL,'Los indicadores muestran tus pendientes, las OT en ejecución, los partes por revisar y los repuestos por despachar. Cada uno aparece solo si tienes permiso para ver esa información.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',3,'app_operativo',NULL,NULL,'En Por resolver elige Míos para ver lo asignado a ti o Mi área para ver todo lo de tu área, y filtra por Taller, Almacén, Producción, Transporte, Flota o Compras. El botón de cada pendiente abre la pantalla donde se resuelve; el reloj lo pospone hasta mañana.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',4,'app_operativo',NULL,NULL,'La bandeja reúne partes diarios por revisar, órdenes de fabricación con compromiso vencido, viajes programados sin iniciar, reservas de repuestos por despachar, diagnósticos técnicos en borrador, SOLPE por aprobar, certificaciones de equipos que vencen en 30 días y OT en ejecución sin parte desde ayer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',5,'app_operativo',NULL,NULL,'En la columna derecha, Aria te avisa de certificaciones por vencer, viajes atrasados y OT con mucho tiempo en ejecución; Mi día lista tus OT programadas y en ejecución, y Accesos rápidos te lleva al Planner, a Nueva OT, a la Bandeja de OT y al Monitor de viajes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',6,'app_operativo',NULL,NULL,'Para preguntar o registrar algo usa el cuadro Pregúntale a Aria o el robot de Aria, que está disponible en todas las pantallas de Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',7,'app_operativo',NULL,NULL,'En celular y tablet el menú se abre con el botón ☰ de arriba a la izquierda; ahí también están las notificaciones, el modo oscuro y la salida.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_caja_chica','proceso',NULL,'Ciclo del fondo de Caja Chica','Controla un fondo desde su creación hasta el arqueo y el cierre con saldo cero.','["src/pages_fin.jsx#CajaChica","src/components/NuevoEgreso.jsx#NuevoEgreso","src/components/CerrarFondoModal.jsx#CerrarFondoModal"]'::jsonb,'3d2ec4ac0a 2c804b78dc e7344f6212')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',1,'caja','caja','crear','Crea el fondo con su responsable, importe, moneda y origen del dinero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',2,'caja',NULL,NULL,'Registra cada egreso con Nuevo egreso: tipo de gasto, categoría del Estado de Resultados, comprobante adjunto y revisión final.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',3,'caja',NULL,NULL,'Cuando el fondo necesite reposición, presenta la rendición del periodo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',4,'caja','caja','aprobar','Revisa y aprueba o rechaza la rendición para reponer el fondo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',5,'caja',NULL,NULL,'Realiza el arqueo con el efectivo contado y revisa las diferencias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_caja_chica',6,'caja','caja','editar','Cierra el fondo dejando el saldo en cero: transfiere lo que quede a otra caja abierta o devuélvelo a una cuenta bancaria.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('proceso_solpe_pago','proceso',NULL,'De la SOLPE al pago conciliado','Sigue una compra desde la solicitud interna hasta su pago y conciliación bancaria.','["src/pages_ops.jsx#SOLPE","src/pages_ops.jsx#BandejaSourcing","src/pages_ops.jsx#OrdenesCompra","src/pages_ops.jsx#Recepciones","src/pages_fin.jsx#CxP","src/pages_fin.jsx#Tesoreria"]'::jsonb,'e43d59cb5b 59f4c3339c 0fbfbec78b 4edd4b32ac d66ee1335d b0397fbc8c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',1,'solpe',NULL,NULL,'Crea la SOLPE con Nueva SOLPE, agrega los ítems y envíala. Quien la atiende puede generar la orden de compra desde la propia SOLPE.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',2,'ordenes_compra',NULL,NULL,'Si los materiales se compran a varios proveedores, usa la Bandeja de Sourcing para asignar un proveedor por línea y generar una orden de compra por proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',3,'ordenes_compra',NULL,NULL,'Revisa la orden de compra, sus datos y su estado de atención.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',4,'recepciones',NULL,NULL,'Registra la recepción de lo comprado con Nueva recepción y confirma las cantidades. La factura del proveedor puede completarse después con Completar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',5,'cxp',NULL,NULL,'Revisa la cuenta por pagar generada para la compra y su vencimiento antes de programar el pago.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('proceso_solpe_pago',6,'tesoreria',NULL,NULL,'Registra el pago y concílialo con el movimiento del extracto bancario en Match Bancario.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tesoreria','pantalla','tesoreria','Tesorería y match bancario','Consulta saldos y flujo de caja, concilia movimientos con el extracto del banco y registra movimientos manuales y transferencias entre cuentas propias.','["src/pages_fin.jsx#Tesoreria","src/services/tesoreriaService.js"]'::jsonb,'b0397fbc8c 5f79da0382')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',1,'tesoreria',NULL,NULL,'En la pestaña Flujo de caja revisa las cuentas bancarias, sus saldos por moneda y la proyección a 90 días. Si se proyecta un saldo negativo, la pantalla muestra una alerta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',2,'tesoreria',NULL,NULL,'En Extracto banco usa Importar extracto para cargar los movimientos del banco desde un archivo CSV. El historial de lotes permite revisar lo importado y borrar un lote cargado por error.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',3,'tesoreria',NULL,NULL,'En Match Bancario compara los movimientos del sistema con los del extracto. Selecciona ambos lados y usa Confirmar match; verifica cuenta, fecha e importe antes de confirmar. Un match se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',4,'tesoreria',NULL,NULL,'Usa Movimiento manual para registrar un ingreso o egreso que no proviene de otro módulo, indicando cuenta, fecha, monto y referencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',5,'tesoreria','tesoreria','crear','Para mover dinero entre cuentas propias elige Movimiento manual y el tipo Transferencia entre cuentas. Indica cuenta de origen y de destino, fecha y monto; ambas deben estar activas, ser de la misma sociedad y no ser cuentas de detracciones. Si las monedas son distintas, ingresa el tipo de cambio en soles por unidad extranjera; la pantalla muestra el monto recibido y la diferencia referencial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tesoreria',6,'tesoreria',NULL,NULL,'Usa Agregar cuenta para registrar una cuenta bancaria con su sociedad y su saldo inicial.');
